package com.yeyamo_mobile.api.gamification_service.infrastructure.outbox;import java.time.Instant;import java.util.UUID;import jakarta.persistence.*;
@Entity@Table(name="gamification_outbox")public class GamificationOutboxEvent{@Id UUID id;@Column(name="aggregate_id",nullable=false,length=120)String aggregateId;@Column(name="event_type",nullable=false,length=120)String eventType;@Column(nullable=false,columnDefinition="TEXT")String payload;@Column(name="occurred_at",nullable=false)Instant occurredAt;@Column(name="published_at")Instant publishedAt;@Column(nullable=false)int attempts;@Column(name="last_error",length=1000)String lastError;}
